//! The KDF (RFC 9946 §5.4.1, Appendix A; ADR 0001) against known-answer
//! vectors generated by OpenSSL's KBKDF (`cargo xtask kat`; provenance is in
//! the vector file's header).

use super::common;

use crate::wire::auth::derive_keys;
use common::unhex;

const VECTORS: &str = include_str!("vectors/kdf-openssl.txt");

/// (Shared Key, authUnixTime, 64-octet output) for every vector in the file.
fn vectors() -> Vec<(Vec<u8>, u32, Vec<u8>)> {
    VECTORS
        .lines()
        .filter(|line| !line.starts_with('#') && !line.trim().is_empty())
        .map(|line| {
            let fields: Vec<&str> = line.split_whitespace().collect();
            let [key, time, output] = fields[..] else {
                panic!("malformed vector line: {line}");
            };
            (unhex(key), time.parse().unwrap(), unhex(output))
        })
        .collect()
}

// KDF in counter mode, HMAC-SHA-256, label "UDPSTP", context = decimal
// authUnixTime, r = 32, 512 bits; client key first.
#[udpstp_req::req(
    "RFC9946-5.4.1-1",
    "RFC9946-5.4.1-2",
    "RFC9946-5.4.1-3",
    "RFC9946-5.4.1-4",
    "RFC9946-5.4.1-5",
    "RFC9946-5.4.1-6",
    "RFC9946-12.2-L1"
)]
#[test]
fn derived_keys_match_every_openssl_vector() {
    let vectors = vectors();
    assert!(!vectors.is_empty(), "the vector file has vectors");
    for (key, time, output) in vectors {
        let keys = derive_keys(&key, time);
        assert_eq!(
            keys.client().as_slice(),
            &output[..32],
            "Client Authentication Key for key {key:02x?}, authUnixTime {time}"
        );
        assert_eq!(
            keys.server().as_slice(),
            &output[32..],
            "Server Authentication Key for key {key:02x?}, authUnixTime {time}"
        );
    }
}

// The vector file covers what ADR 0001 and the ticket ask for: both
// authUnixTime extremes, and Shared Keys with zero bytes inside them (which
// must not be truncated).
#[test]
fn vectors_cover_authunixtime_extremes_and_zero_bytes_in_keys() {
    let times: Vec<u32> = vectors().iter().map(|(_, t, _)| *t).collect();
    assert!(times.contains(&0));
    assert!(times.contains(&u32::MAX));
    assert!(vectors().iter().any(|(key, _, _)| key[1..].contains(&0)));
}
